let signedIn=null,accountRecords=new Map(),accountVersions=new Map(),syncTimer=null,syncChain=Promise.resolve(),syncState='Đang kết nối',syncConflict=null,accountBusy=false,authMode='login';
const isLocalApp=['127.0.0.1','localhost'].includes(location.hostname),apiPrefix='/api/tram';
async function accountAPI(route,options={}){const res=await fetch(apiPrefix+route,{...options,credentials:'same-origin',headers:{'Content-Type':'application/json',...options.headers}});let data;try{data=await res.json()}catch{throw Error('Ứng dụng cục bộ chưa chạy hoặc endpoint không sẵn sàng.')}if(!res.ok){const e=Error(data.error||'Không xử lý được yêu cầu.');e.status=res.status;throw e}return data}
function setSync(message){syncState=message;const el=$('#accountSync');if(el)el.textContent=message}
function scopedKey(name){return 'tram-user-'+signedIn?.id+'-'+name}
const pendingSnapshots=new Map();
persist=function(){if(!signedIn)return;try{localStorage.setItem(scopedKey('projects'),JSON.stringify(app))}catch{toast('Bộ nhớ trình duyệt đầy. Đang lưu qua máy chủ.')};for(const p of app.projects){const serialized=JSON.stringify(p);if(serialized!==accountRecords.get(p.id))pendingSnapshots.set(p.id,structuredClone(p))}if(pendingSnapshots.size&&!syncConflict){setSync('Đang lưu…');clearTimeout(syncTimer);syncTimer=setTimeout(()=>flushProjects().catch(()=>{}),500)}};
async function flushProjects(){clearTimeout(syncTimer);if(!signedIn||syncConflict)return;const userId=signedIn.id;const next=syncChain.then(async()=>{for(const[id,snapshot]of [...pendingSnapshots]){if(!signedIn||signedIn.id!==userId)return;try{const record=await accountAPI('/projects',{method:'PUT',body:JSON.stringify({project:snapshot,expectedVersion:accountVersions.get(id)||0})});accountVersions.set(id,record.version);accountRecords.set(id,JSON.stringify(record.project));if(JSON.stringify(pendingSnapshots.get(id))===JSON.stringify(snapshot))pendingSnapshots.delete(id);if(accountMeta)accountMeta.set(id,record);}catch(e){if(e.status===409){syncConflict={id,message:e.message};setSync('Có chỉnh sửa mới ở phiên khác');toast('Có xung đột phiên bản. Mở Tài khoản để giữ bản riêng hoặc tải bản mới.')}else setSync('Chưa lưu được: '+e.message);throw e}}setSync(pendingSnapshots.size?'Đang lưu…':'Đã lưu lên máy chủ')});syncChain=next.catch(()=>{});return next}
window.tramFlush=async()=>{await flushProjects();if(syncConflict||pendingSnapshots.size)throw Error('Dự án chưa đồng bộ. Kiểm tra mục Tài khoản trước khi gửi việc.')};
const accountMeta=new Map();
function resetPrivateState(){stop();clearTimeout(realPoll);realPoll=null;realJob=null;realFileRecords=[];workbenchHealth=null;workbenchStatus='';gatewayToken='';remoteAgents=[];realResults=[];gateway={url:'http://127.0.0.1:4320',bindings:{}};pendingSnapshots.clear();accountRecords.clear();accountVersions.clear();accountMeta.clear();syncConflict=null;clearTimeout(syncTimer);if(window.tramDrafts)window.tramDrafts.clear();window.dispatchEvent(new Event('tram:account-change'));}
async function loadAccount(user){resetPrivateState();signedIn=user;const result=await accountAPI('/projects');const records=result.projects.filter(r=>validProject(r.project));for(const r of records){accountRecords.set(r.project.id,JSON.stringify(r.project));accountVersions.set(r.project.id,r.version);accountMeta.set(r.project.id,r)}let cached;try{cached=JSON.parse(localStorage.getItem(scopedKey('projects')))}catch{};const projects=records.map(r=>r.project);if(!projects.length){const p={...defaultProject(),id:uid('project')};projects.push(p)}app={version:1,active:projects.some(p=>p.id===cached?.active)?cached.active:projects[0].id,projects,motion:cached?.motion!==false};render();await flushProjects();$('#authDialog')?.close();updateAccountButton();restoreProjectJobs();}
function updateAccountButton(){accountButton.textContent=signedIn?'◉':'♙';accountButton.title=signedIn?'Tài khoản · '+signedIn.name:'Đăng nhập / Đăng ký';accountButton.setAttribute('aria-label',signedIn?'Tài khoản · '+signedIn.name:'Đăng nhập / Đăng ký')}
const accountButton=document.createElement('button');accountButton.textContent='♙';accountButton.title='Đăng nhập / Đăng ký';accountButton.setAttribute('aria-label','Đăng nhập / Đăng ký');accountButton.onclick=()=>signedIn?openPanel('account'):showAuth();$('.rail').insertBefore(accountButton,$('.rail-end'));
const authDialog=document.createElement('dialog');authDialog.id='authDialog';authDialog.addEventListener('cancel',e=>e.preventDefault());document.body.append(authDialog);
function showAuth(message=''){if(!isLocalApp){openPanel('account');return}if($('#welcome').open)$('#welcome').close();authDialog.innerHTML=`<div class="eyebrow">TRẠM CÔNG NGHỆ / TÀI KHOẢN CỤC BỘ</div><h2>${authMode==='login'?'Chào mừng trở lại':'Tạo tài khoản của bạn'}</h2><p class="muted">Tài khoản lưu trên máy chạy Trạm. Dự án, tài liệu và lịch sử chỉ mở cho người được cấp quyền. Không phải đăng nhập ChatGPT.</p><form id="authForm">${authMode==='register'?'<label>Tên hiển thị<input name="name" required maxlength="80" autocomplete="name"></label>':''}<label>Email<input type="email" name="email" required maxlength="200" autocomplete="username"></label><label>Mật khẩu<input type="password" name="password" required minlength="12" maxlength="200" autocomplete="${authMode==='register'?'new-password':'current-password'}"></label><p class="muted">Ít nhất 12 ký tự. Bản cục bộ chưa có đặt lại mật khẩu qua email.</p><p id="authError" class="form-error" role="alert">${escapeHTML(message)}</p><button class="primary full" ${accountBusy?'disabled':''}>${authMode==='login'?'Đăng nhập':'Đăng ký'}</button></form><button class="text-switch" id="authSwitch">${authMode==='login'?'Chưa có tài khoản? Đăng ký':'Đã có tài khoản? Đăng nhập'}</button>`;if(!authDialog.open)authDialog.showModal();$('#authSwitch').onclick=()=>{authMode=authMode==='login'?'register':'login';showAuth()};$('#authForm').onsubmit=async e=>{e.preventDefault();if(accountBusy)return;accountBusy=true;const button=e.target.querySelector('button');button.disabled=true;try{const payload=Object.fromEntries(new FormData(e.target));const result=await accountAPI('/auth/'+authMode,{method:'POST',body:JSON.stringify(payload)});await loadAccount(result.user);toast('Đã đăng nhập. Dự án được lưu theo tài khoản.')}catch(err){$('#authError').textContent=err.message}finally{accountBusy=false;if(button.isConnected)button.disabled=false}};}
panelExtensions.account=async function(){if(!isLocalApp){panel('Tài khoản & ứng dụng thật','<p class="notice">Bản đang host là giao diện xem thử. Đăng ký, Codex, tài liệu và lịch sử chạy trên ứng dụng cục bộ tại http://127.0.0.1:4318. Chưa triển khai máy chủ nhiều người trên Internet.</p>');return}if(!signedIn){showAuth();return}const meta=accountMeta.get(project().id);panel('Tài khoản & cộng tác',`<article class="card"><h3>${escapeHTML(signedIn.name)}</h3><p>${escapeHTML(signedIn.email)}</p><p id="accountSync" class="muted">${escapeHTML(syncState)}</p><button id="logout">Lưu & đăng xuất</button></article>${syncConflict?`<div class="step-gate">${escapeHTML(syncConflict.message)}<div class="button-row"><button id="keepConflict">Giữ bản của tôi thành dự án riêng</button><button id="reloadConflict">Tải bản mới từ máy chủ</button></div></div>`:''}<h3 class="section-label">DỰ ÁN HIỆN TẠI</h3><article class="card"><h3>${escapeHTML(project().name)}</h3><p class="muted">Phiên bản máy chủ: ${meta?.version||1}<br>${(meta?.members||[]).map(m=>escapeHTML(m.name)+' · '+escapeHTML(m.email)).join('<br>')}</p>${meta?.ownerId===signedIn.id?'<form id="inviteForm"><label>Thêm người đã đăng ký trên máy chủ<input name="email" required type="email" placeholder="email@nhom.vn"></label><button class="full">Thêm cộng tác viên</button></form>':'<p class="muted">Bạn đang cộng tác trong dự án này.</p>'}</article><button class="full" id="editHistory">Xem lịch sử chỉnh sửa theo người</button><h3 class="section-label">THÔNG BÁO TELEGRAM</h3><div id="notificationSettings"><p class="muted">Đang đọc cấu hình…</p></div><p class="notice">Bản này phục vụ cá nhân hoặc nhóm nhỏ trên cùng máy chủ cục bộ. Chưa mở ra Internet; chia sẻ ngoài máy cần triển khai HTTPS và vận hành riêng.</p>`);$('#logout').onclick=async()=>{try{await window.tramFlush();await accountAPI('/auth/logout',{method:'POST',body:'{}'});resetPrivateState();signedIn=null;app={version:1,active:'logged-out',projects:[{...defaultProject(),id:'logged-out'}],motion:true};closePanel();render();showAuth();updateAccountButton()}catch(e){toast(e.message)}};if($('#inviteForm'))$('#inviteForm').onsubmit=async e=>{e.preventDefault();try{await window.tramFlush();const rec=await accountAPI('/projects/'+project().id+'/members',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});accountMeta.set(project().id,rec);renderPanel('account');toast('Đã thêm cộng tác viên.')}catch(err){toast(err.message)}};$('#editHistory').onclick=()=>openPanel('edit-history');if($('#keepConflict'))$('#keepConflict').onclick=async()=>{const copy=structuredClone(app.projects.find(p=>p.id===syncConflict.id));pendingSnapshots.delete(copy.id);copy.id=uid('project');copy.name=(copy.name+' (bản riêng)').slice(0,100);app.projects.push(copy);app.active=copy.id;syncConflict=null;render();await flushProjects();toast('Đã lưu bản riêng. Bản gốc trên máy chủ được giữ nguyên.')};if($('#reloadConflict'))$('#reloadConflict').onclick=async()=>{await loadAccount(signedIn);openPanel('account')};try{const n=await accountAPI('/notifications');if(drawerView!=='account'||!$('#notificationSettings'))return;$('#notificationSettings').innerHTML=`<form id="notificationForm"><label>Bot token ${n.hasToken?'· đã lưu, để trống để giữ nguyên':''}<input type="password" name="botToken" autocomplete="off" placeholder="Chỉ gửi tới máy chủ cục bộ"></label><label>Chat ID<input name="chatId" value="${escapeHTML(n.chatId)}" placeholder="ID cá nhân hoặc nhóm"></label><label class="checkbox-label"><input type="checkbox" name="enabled" ${n.enabled?'checked':''}> Báo khi tác vụ hoàn tất hoặc lỗi</label><p class="muted">Thông báo chỉ gồm tên dự án và trạng thái; không gửi tài liệu hay mã nguồn. Token được mã hóa phía máy chủ.</p><button class="primary full">Lưu Telegram</button></form><button id="testTelegram" class="full" style="margin-top:10px">Gửi thông báo kiểm tra</button><p class="muted">Trạng thái lần trước: ${escapeHTML(n.lastStatus||'Chưa gửi')}</p>`;$('#notificationForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{await accountAPI('/notifications',{method:'PUT',body:JSON.stringify({botToken:f.botToken||undefined,chatId:f.chatId.trim(),enabled:!!f.enabled})});toast('Đã lưu cấu hình Telegram.');renderPanel('account')}catch(err){toast(err.message)}};$('#testTelegram').onclick=async()=>{try{await accountAPI('/notifications/test',{method:'POST',body:'{}'});toast('Telegram đã nhận thông báo kiểm tra.')}catch(err){toast(err.message)}};}catch(e){if($('#notificationSettings'))$('#notificationSettings').textContent=e.message}}
panelExtensions['edit-history']=async()=>{panel('Lịch sử chỉnh sửa','<p class="muted">Đang đọc lịch sử từ máy chủ…</p>');try{await window.tramFlush();const h=await accountAPI('/projects/'+project().id+'/history');if(drawerView!=='edit-history')return;panel('Lịch sử chỉnh sửa',`<p class="muted">Phiên bản hiện tại: ${h.version}. Người sửa được xác định bởi phiên đăng nhập phía máy chủ.</p>${h.audit.slice().reverse().map(a=>`<article class="card"><small>v${a.version} · ${new Date(a.time).toLocaleString('vi-VN')}</small><h3>${escapeHTML(a.userName)}</h3><p>${escapeHTML(a.action)}<br>${escapeHTML(a.detail)}</p></article>`).join('')}<h3 class="section-label">KHÔI PHỤC PHIÊN BẢN</h3>${h.history.slice().reverse().map(v=>`<button class="card card-button" data-restore="${v.version}">Khôi phục nội dung v${v.version} · ${new Date(v.time).toLocaleString('vi-VN')}<small> · tạo phiên bản mới, không xóa lịch sử</small></button>`).join('')||'<p class="muted">Chưa có phiên bản trước.</p>'}`);$$('[data-restore]').forEach(b=>b.onclick=async()=>{try{const rec=await accountAPI('/projects/'+project().id+'/restore',{method:'POST',body:JSON.stringify({version:Number(b.dataset.restore),expectedVersion:accountVersions.get(project().id)})});const index=app.projects.findIndex(p=>p.id===rec.project.id);app.projects[index]=rec.project;accountVersions.set(rec.project.id,rec.version);accountRecords.set(rec.project.id,JSON.stringify(rec.project));accountMeta.set(rec.project.id,rec);render();toast('Đã khôi phục thành phiên bản mới.')}catch(e){toast(e.message)}})}catch(e){panel('Lịch sử chỉnh sửa',`<p class="notice">${escapeHTML(e.message)}</p>`)}};
async function restoreProjectJobs(){if(!signedIn||!isLocalApp)return;try{const pid=project().id;const [f,j]=await Promise.all([accountAPI('/files?projectId='+pid),accountAPI('/jobs?projectId='+pid)]);if(pid!==project().id)return;realFileRecords=realFileRecords.filter(x=>x.projectId!==pid).concat(f.files);realJob=j.jobs[0]||null;if(realJob&&['running','queued'].includes(realJob.state))pollRealJob();if(drawerView==='workbench')renderPanel('workbench')}catch{}}
window.tramRestoreJobs=restoreProjectJobs;
if(isLocalApp){accountAPI('/auth/me').then(result=>result.user?loadAccount(result.user):showAuth()).catch(e=>showAuth(e.message));$('#ideaButton').onclick=()=>openPanel('workbench');}else updateAccountButton();
